package com.gestao.financas.service;
import com.gestao.financas.entity.PasswordResetToken;import com.gestao.financas.repository.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.UUID;
@Service public class PasswordService {
 private final UserRepository users;private final PasswordResetTokenRepository tokens;private final JavaMailSender mail;private final PasswordEncoder encoder;private final String baseUrl;
 public PasswordService(UserRepository u,PasswordResetTokenRepository t,JavaMailSender m,PasswordEncoder e,@Value("${app.frontend.base-url:http://localhost:3000}") String b){users=u;tokens=t;mail=m;encoder=e;baseUrl=b;}
 @Transactional public void createPasswordResetToken(String email){users.findByEmail(email).ifPresent(u->{tokens.findByUser(u).ifPresent(tokens::delete);String value=UUID.randomUUID().toString();PasswordResetToken token=new PasswordResetToken();token.setToken(value);token.setUser(u);token.setExpiryDate(LocalDateTime.now().plusHours(1));tokens.save(token);SimpleMailMessage message=new SimpleMailMessage();message.setTo(u.getEmail());message.setSubject("Redefinição de senha");message.setText("Use este token para redefinir sua senha: "+value+"\nAplicação: "+baseUrl);mail.send(message);});}
 @Transactional public void resetPassword(String value,String newPassword){if(newPassword==null||newPassword.length()<8||newPassword.length()>72)throw new IllegalArgumentException("A senha deve ter entre 8 e 72 caracteres.");PasswordResetToken t=tokens.findByToken(value).orElseThrow(()->new IllegalArgumentException("Token inválido ou expirado."));if(t.getExpiryDate().isBefore(LocalDateTime.now())){tokens.delete(t);throw new IllegalArgumentException("Token inválido ou expirado.");}var u=t.getUser();u.setPassword(encoder.encode(newPassword));users.save(u);tokens.delete(t);}
}